// Loop over input items and add a new field called 'myNewField' to the JSON of each one
const requests = $input.all().map(item => item.json);

const total = requests.length;

const approved = requests.filter(item => item.status  === 'Approved');

const Rejected = requests.filter(item => item.status === 'Rejected');

const pending = requests.filter(item => item.status === 'Pending Approval');

const totalApprovedDays = approved.reduce((sum, item) => sum + Number(item.leaveDays), 0);

const approvalRate = total > 0 ? (approved.length / total) * 100 : 0;

const rejectionRate = total > 0 ? (Rejected.length / total) * 100 : 0;

return[{
  json: {
    totalRequests: total,
    approvedRequests: approved.length,
    rejectedRequests: Rejected.length,
    pendingRequests: pending.length,
    totalApprovedDays: totalApprovedDays,
    approvalRate: approvalRate.toFixed(2) +
    '%',
    rejectionRate: rejectionRate.toFixed(2) +
    '%'



  }
}];

